import{r as n}from"./request-DhJtU_Kj.js";const o=e=>encodeURIComponent(String(e||"")),s={getList(e){return n.get("/mails",{params:e})},getDetail(e){return n.get(`/mails/${o(e)}`)},mediaUrl(e,t){const a=encodeURIComponent(localStorage.getItem("auth_token")||"");return`/api/mails/${o(e)}/media/${encodeURIComponent(String(t||""))}?token=${a}`},attachmentUrl(e,t){const a=encodeURIComponent(localStorage.getItem("auth_token")||"");return`/api/mails/${o(e)}/attachments/${encodeURIComponent(String(t||""))}?token=${a}`},saveDraft(e,t){return n.post(`/mails/${o(e)}/save`,{body:t})},approve(e){return n.post(`/mails/${o(e)}/approve`)},reject(e,t){return n.post(`/mails/${o(e)}/reject`,{reason:t})},delete(e){return n.post("/mails/delete",{message_ids:e})},getStats(){return n.get("/mails/stats")}};export{s as m};
